package com.serratocreations.phovo.core.database.entities

import androidx.room.Embedded
import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Server only: a media row's position in the catalog that clients page through.
 *
 * [catalogSeq] is generated by SQLite (`AUTOINCREMENT`), so it only goes up and is never reused,
 * even after rows are deleted. Writing an entry with `REPLACE` for an [assetHash] that already has
 * one deletes the old entry and inserts a new one with the next value, so a changed row moves to
 * the end of the catalog and clients fetch it again.
 *
 * The unique index on [assetHash] is what makes `REPLACE` find the existing entry: without it every
 * write would add another entry for the same asset.
 */
@Entity(indices = [Index(value = ["assetHash"], unique = true)])
data class CatalogEntryEntity(
    @PrimaryKey(autoGenerate = true) val catalogSeq: Long = 0,
    val assetHash: String
)

/** A metadata row with its position in the server's catalog. */
data class CatalogMediaItem(
    @Embedded val mediaItemMetadataEntity: MediaItemMetadataEntity,
    val catalogSeq: Long
)
